import assert from "node:assert/strict";
import {readFileSync} from "node:fs";
import {PRAY_CANONICAL_DATA_V435930} from "../src/pray/canonical-data.js";
const source=JSON.parse(readFileSync(new URL("../data/pray/immaculate-heart-exact-witness-variant-gate-20261109.v1.json",import.meta.url),"utf8"));
const inventory=JSON.parse(readFileSync(new URL("../data/pray/prayer-source-certification-inventory.v3.json",import.meta.url),"utf8"));
const p=PRAY_CANONICAL_DATA_V435930.prayers.marian_consecration_immaculate_heart;
assert.equal(source.canonicalPrayerId,p.id);
assert.equal(source.schema,"ao.pray.immaculate-heart-consecration-exact-witness-variants.v1");
assert.equal(source.canonical.source,p.sourceUrl);
assert.equal(source.canonical.english,"PUBLISHED_UNCHANGED");
assert.equal(source.disposition.currentCanonicalEnglish,"PRESERVE_UNCHANGED");
assert.equal(source.disposition.originalFrenchSameForm,"NOT_LOCATED");
assert.equal(source.disposition.originalLatinSameForm,"NOT_LOCATED");
assert.equal(source.olderHistoricalWitness.disposition,"ALTERNATE_ENGLISH_FORM_NOT_CURRENT_CANONICAL_TEXT");
assert.equal(source.olderHistoricalWitness.repositoryId,"ML.031-044");
assert.match(source.olderHistoricalWitness.source,/ecommons\.udayton\.edu\/ul_holy_cards\/264/);
assert.equal(source.olderHistoricalWitness.photographedBackSideInspected,false);
assert.equal(source.olderHistoricalWitness.historicalPrintedWitnessAttested,true);
assert.equal(source.canonical.editionSpecificHistoricalAttributionCertified,false);
assert.equal(source.disposition.noGuessedTranslation,true);
assert.equal(source.disposition.noAutomaticRomanRiteOrICRSPAttribution,true);
assert.equal(p.sourceStatus,"VERIFIED_SECONDARY");
assert.equal(p.en.length>850,true);
assert.equal(p.la,"");
assert.equal(p.fr,"");
assert.equal(p.provenance.languages.en,"VERIFIED_SECONDARY");
assert.equal(p.provenance.languages.fr,"SOURCE_PENDING");
assert.equal(p.provenance.languages.la,"SOURCE_PENDING");
assert.match(p.note,/1960 Marian Library holy card contains a distinct consecration/i);
assert.match(p.provenance.note,/circa-1960 Fatima holy card/);
assert.match(p.en,/receive Holy Communion regularly/i);
assert.match(p.en,/Most Holy Mother of God/);
assert.match(p.en,/Most Blessed Virgin/);
assert.match(p.en,/Most Gracious Virgin and Mother/);
assert.match(p.en,/the impurity which Thou didst lament/);
assert.doesNotMatch(p.en,/First Saturday of every month/);
assert.doesNotMatch(p.en,/deluge of impurity/);
assert.equal(source.olderHistoricalWitness.differences.communion,"First Saturday of every month");
assert.equal(source.canonical.keyCues.communion,"receive Holy Communion regularly");
assert.equal(source.canonical.keyCues.fiveDecades,"five decades of the Rosary each day");
assert.equal(source.sources.length,4);
assert.equal(source.sources.filter(s=>s.scope.includes("same-form")).length,1);
assert.ok(source.sources.every(s=>/^https:\/\//.test(s.url)));
assert.ok(Array.isArray(inventory.canonicalPrayers)||Array.isArray(inventory.entries)||
 typeof inventory==="object","Existing source certification registry remains available");
console.log("PASS Immaculate Heart: canonical English preserved, distinct historical 1960 card documented, 0 invented FR/LA texts, no alternate consecration promoted");
